#[doc = "A plane `a x + b y + c z + d = 0`, stored as `a e1 + b e2 + c e3 + d e0`: the vectors (grade 1). As a versor it is a reflection."]
///
/// Blades, in coefficient order: `[e1, e2, e3, e0]`.
///
/// `S` lists the open slots: `Plane` (that is, `Plane<()>`) is a value, `Plane<(A,)>` a
/// linear map from `A`, `Plane<(A, B)>` a bilinear map. `T` is the coefficient type. `O` is
/// the orientation of the output, extrinsic by default (ADR-051).
#[repr(C)]
pub struct Plane<S: gx::Slots = (), T: gx::Coef = f64, O: gx::Orientation = gx::Extrinsic> {
    /// Coefficients, output first: `c[i]` is the slot array of blade `i`.
    pub c: [S::Arr<T>; 4],
    o: core::marker::PhantomData<O>,
}

impl<S: gx::Slots, T: gx::Coef, O: gx::Orientation> Clone for Plane<S, T, O> {
    #[inline(always)]
    fn clone(&self) -> Self {
        *self
    }
}

impl<S: gx::Slots, T: gx::Coef, O: gx::Orientation> Copy for Plane<S, T, O> {}

impl<S: gx::Slots, T: gx::Coef, O: gx::Orientation> PartialEq for Plane<S, T, O> {
    fn eq(&self, other: &Self) -> bool {
        self.c == other.c
    }
}

impl<S: gx::Slots, T: gx::Coef, O: gx::Orientation> core::fmt::Debug for Plane<S, T, O> {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        let mut d = f.debug_struct(if O::SIGN < 0 { "intrinsic Plane" } else { "Plane" });
        for (b, c) in <Plane as gx::Kind>::BLADES.iter().zip(self.c.iter()) {
            d.field(b, c);
        }
        d.finish()
    }
}

// SAFETY: `Arr<X>` is `[X; 4]`, the layout `gx::FlatKind` promises.
unsafe impl<O: gx::Orientation> gx::FlatKind for Plane<(), f64, O> {}

impl<O: gx::Orientation> gx::Kind for Plane<(), f64, O> {
    const N: usize = 4;
    const NAME: &'static str = "Plane";
    const MODULE: &'static str = module_path!();
    const BLADES: &'static [&'static str] = &["e1", "e2", "e3", "e0"];
    type Arr<X: gx::Elem> = [X; 4];
    type Mv<S: gx::Slots, T: gx::Coef> = Plane<S, T, O>;
    type Scalar = Scalar;
    type Orientation = O;
    const DEFAULT_INTRINSIC: bool = false;
    #[inline(always)]
    fn arr_from_fn<X: gx::Elem>(mut f: impl FnMut(usize) -> X) -> [X; 4] {
        [f(0), f(1), f(2), f(3)]
    }
    #[inline(always)]
    fn arr_map<X: gx::Elem, Y: gx::Elem>(a: &[X; 4], mut f: impl FnMut(&X) -> Y) -> [Y; 4] {
        [f(&a[0]), f(&a[1]), f(&a[2]), f(&a[3])]
    }
    #[inline(always)]
    fn arr_zip<X: gx::Elem, Y: gx::Elem, Z: gx::Elem>(
        a: &[X; 4],
        b: &[Y; 4],
        mut f: impl FnMut(&X, &Y) -> Z,
    ) -> [Z; 4] {
        [f(&a[0], &b[0]), f(&a[1], &b[1]), f(&a[2], &b[2]), f(&a[3], &b[3])]
    }
}

