    /// Move open slot `I` to the front, so that `.of(x)` fills it: `m.at::<1>().of(x)`.
    #[inline(always)]
    pub fn at<const I: usize>(self) -> Plane<<S as gx::__private::MoveToFront<I>>::Moved, T, O>
    where
        S: gx::__private::MoveToFront<I>,
    {
        Plane { o: core::marker::PhantomData, c: self.c.map(|col| <S as gx::__private::MoveToFront<I>>::move_arr(&col)) }
    }

    /// Contract the output with open slot `I` (which must be of kind `Plane`): a trace with no
    /// metric, leaving a scalar with the other slots (numga's `trace(slot)`).
    #[inline(always)]
    pub fn trace_at<const I: usize>(self) -> <Plane<<S as gx::__private::MoveToFront<I>>::Moved, T, O> as gx::TraceFirst>::Output
    where
        S: gx::__private::MoveToFront<I>,
        Plane<<S as gx::__private::MoveToFront<I>>::Moved, T, O>: gx::TraceFirst,
    {
        gx::TraceFirst::trace_first(self.at::<I>())
    }

    /// Fill every open slot of `x`'s kind with the value `x`; the other slots stay open.
    #[inline(always)]
    pub fn fill<X>(self, x: X) -> Plane<<S as gx::__private::FillList<X::Kind>>::Out, T, O>
    where
        X: gx::Extensor<Slots = (), Coef = T>,
        S: gx::__private::FillList<X::Kind>,
    {
        let xc = x.coeffs();
        Plane { o: core::marker::PhantomData, c: self.c.map(|col| <S as gx::__private::FillList<X::Kind>>::fill(&col, xc)) }
    }

