impl<S: gx::Slots, T: gx::Coef, O: gx::Orientation> core::ops::Add for Plane<S, T, O> {
    type Output = Self;
    #[inline(always)]
    fn add(self, rhs: Self) -> Self {
        Plane { o: core::marker::PhantomData, c: core::array::from_fn(|i| (gx::__private::SlotArr::<S, T>(self.c[i]) + gx::__private::SlotArr::<S, T>(rhs.c[i])).0) }
    }
}

impl<S: gx::Slots, T: gx::Coef, O: gx::Orientation> core::ops::Sub for Plane<S, T, O> {
    type Output = Self;
    #[inline(always)]
    fn sub(self, rhs: Self) -> Self {
        Plane { o: core::marker::PhantomData, c: core::array::from_fn(|i| (gx::__private::SlotArr::<S, T>(self.c[i]) - gx::__private::SlotArr::<S, T>(rhs.c[i])).0) }
    }
}

impl<S: gx::Slots, T: gx::Coef, O: gx::Orientation> core::iter::Sum for Plane<S, T, O> {
    /// The sum of values or of maps; zero for none.
    #[inline]
    fn sum<I: Iterator<Item = Self>>(iter: I) -> Self {
        iter.fold(Self::zero(), |a, b| a + b)
    }
}

impl<S: gx::Slots, T: gx::Coef, O: gx::Orientation> core::ops::AddAssign for Plane<S, T, O> {
    #[inline(always)]
    fn add_assign(&mut self, rhs: Self) {
        *self = *self + rhs;
    }
}

impl<S: gx::Slots, T: gx::Coef, O: gx::Orientation> core::ops::SubAssign for Plane<S, T, O> {
    #[inline(always)]
    fn sub_assign(&mut self, rhs: Self) {
        *self = *self - rhs;
    }
}

