impl<T: gx::Real, O: gx::Orientation> Plane<(), T, O> {
    /// The squared norm: the scalar part of `x ~x`.
    #[inline(always)]
    pub fn norm_squared(self) -> T {
        let x = self.c;
        let t1 = x[1] * x[1];
        let t3 = x[0].mul_add(x[0], t1);
        let t4 = x[2].mul_add(x[2], t3);
        t4
    }

    /// The norm, `sqrt(|norm_squared|)`.
    #[inline(always)]
    pub fn norm(self) -> T {
        self.norm_squared().abs().sqrt()
    }

    /// The inverse under the geometric product, `~x (x ~x)â»Â¹` (17 mul, 7 add, 1 div).
    #[inline(always)]
    pub fn inverse(self) -> Plane<(), T, O> {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[1] * x[1];
        let t2 = x[2] * x[2];
        let t5 = t0 * t2;
        let t6 = t1 * t1;
        let t9 = t0.mul_add(t0, t6);
        let t10 = t2.mul_add(t2, t9);
        let t11 = t0.mul_add(t1, t5);
        let t12 = t1.mul_add(t2, t11);
        let t14 = t12.mul_add(T::from_i64(2), t10);
        let t15 = t14.recip();
        let t17 = t1 * t15;
        let t19 = t0.mul_add(t15, t17);
        let t20 = t2.mul_add(t15, t19);
        let t21 = x[0] * t20;
        let t22 = x[1] * t20;
        let t23 = x[2] * t20;
        let t24 = x[3] * t20;
        Plane::from_coeffs([t21, t22, t23, t24])
    }

    /// [`inverse`](Self::inverse), or `None` where `x` has no inverse to working precision:
    /// where `x ~x`, the Study number `N` the inverse divides by, is zero next to `x`
    /// (`|N| â¤ n Îµ âxâÂ²`, with `|N|Â²` and `âxâÂ²` the sums of the squared coefficients of `N`
    /// and `x`, and `n = 4` the number of `x`'s), or its norm `d = N conj(N)` is lost to
    /// cancellation (`|d| â¤ n Îµ |N|Â²`), in any lane; or where the inverse is not finite.
    #[inline]
    pub fn try_inverse(self) -> Option<Plane<(), T, O>> {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[1] * x[1];
        let t2 = x[2] * x[2];
        let t6 = t0 * t2;
        let t7 = t1 * t1;
        let t10 = t0 + t1;
        let t11 = t2 + t10;
        let t12 = x[3].mul_add(x[3], t11);
        let t13 = t0.mul_add(t0, t7);
        let t14 = t2.mul_add(t2, t13);
        let t15 = t0.mul_add(t1, t6);
        let t16 = t1.mul_add(t2, t15);
        let t18 = t16.mul_add(T::from_i64(2), t14);
        let (size, d) = (t12, t18);
        let parts = t11 * t11;
        let tol = T::from_i64(4) * T::epsilon();
        if T::all_lt(tol * size, parts.sqrt()) && T::all_lt(tol * parts, d.abs()) {
            Some(self.inverse()).filter(gx::Extensor::is_finite)
        } else {
            None
        }
    }

    /// Scaled to a unit versor, `(x ~x)^(-1/2) x`, so that `x ~x = 1` (`Â±1` when the norm is negative).
    #[inline(always)]
    pub fn unit(self) -> gx::Unit<Self> {
        let x = self.c;
        let p1 = x[1] * x[1];
        let p3 = x[0].mul_add(x[0], p1);
        let p4 = x[2].mul_add(x[2], p3);
        let s0 = (p4).abs().sqrt().recip();
        let t0 = x[0] * s0;
        let t1 = x[1] * s0;
        let t2 = x[2] * s0;
        let t3 = x[3] * s0;
        gx::Unit::new_unchecked(Plane::from_coeffs([t0, t1, t2, t3]))
    }

    /// The same, uncertified: `self` scaled so that `x ~x = 1`, as a plain value. [`unit`](Self::unit)
    /// returns it as a [`gx::Unit`], which the cheaper unit kernels take.
    #[inline(always)]
    pub fn normalized(self) -> Self {
        self.unit().into_inner()
    }

}

impl<T: gx::Coef, O: gx::Orientation> gx::__private::NewtonStep for Plane<(), T, O> {
    /// `(3 â x ~x) x / 2`: one Newton step towards `x ~x = 1`, without a square root.
    #[inline(always)]
    fn newton_step(self) -> Self {
        let x = self.c;
        let t1 = x[1] * x[1];
        let t3 = x[0].mul_add(x[0], t1);
        let t4 = x[2].mul_add(x[2], t3);
        let t6 = (-t4).mul_add(T::from_ratio(1, 3), T::from_i64(1));
        let t7 = x[0] * t6;
        let t8 = x[1] * t6;
        let t9 = x[2] * t6;
        let t10 = x[3] * t6;
        let t11 = t7 * T::from_ratio(3, 2);
        let t12 = t8 * T::from_ratio(3, 2);
        let t13 = t9 * T::from_ratio(3, 2);
        let t14 = t10 * T::from_ratio(3, 2);
        Plane::from_coeffs([t11, t12, t13, t14])
    }

    #[inline(always)]
    fn note_renormalize() {
        T::note_renormalize();
    }
}

