impl<O: gx::Orientation> gx::Kind for Direction<(), f64, O> {
    const N: usize = 3;
    const NAME: &'static str = "Direction";
    const MODULE: &'static str = module_path!();
    const BLADES: &'static [&'static str] = &["e032", "e013", "e021"];
    type Arr<X: gx::Elem> = [X; 3];
    type Mv<S: gx::Slots, T: gx::Coef> = Direction<S, T, O>;
    type Scalar = Scalar;
    type Orientation = O;
    const DEFAULT_INTRINSIC: bool = true;
    #[inline(always)]
    fn arr_from_fn<X: gx::Elem>(mut f: impl FnMut(usize) -> X) -> [X; 3] {
        [f(0), f(1), f(2)]
    }
    #[inline(always)]
    fn arr_map<X: gx::Elem, Y: gx::Elem>(a: &[X; 3], mut f: impl FnMut(&X) -> Y) -> [Y; 3] {
        [f(&a[0]), f(&a[1]), f(&a[2])]
    }
    #[inline(always)]
    fn arr_zip<X: gx::Elem, Y: gx::Elem, Z: gx::Elem>(
        a: &[X; 3],
        b: &[Y; 3],
        mut f: impl FnMut(&X, &Y) -> Z,
    ) -> [Z; 3] {
        [f(&a[0], &b[0]), f(&a[1], &b[1]), f(&a[2], &b[2])]
    }
}

