    /// Coefficient of `e23`.
    #[inline(always)]
    pub fn e23(&self) -> T {
        self.c[1]
    }

    /// Coefficient of `e31`.
    #[inline(always)]
    pub fn e31(&self) -> T {
        self.c[2]
    }

    /// Coefficient of `e12`.
