impl<T: gx::Real, O: gx::Orientation> Translator<(), T, O> {
    /// The squared norm: the scalar part of `x ~x`.
    #[inline(always)]
    pub fn norm_squared(self) -> T {
        let x = self.c;
        let t0 = x[0] * x[0];
        t0
    }

    /// The norm, `sqrt(|norm_squared|)`.
    #[inline(always)]
    pub fn norm(self) -> T {
        self.norm_squared().abs().sqrt()
    }

    /// The inverse under the geometric product, `~x (x ~x)â»Â¹` (8 mul, 0 add, 1 div).
    #[inline(always)]
    pub fn inverse(self) -> Translator<(), T, O> {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[0] * t0;
        let t2 = x[0] * t1;
        let t3 = t2.recip();
        let t4 = t0 * t3;
        let t5 = x[0] * t4;
        let t6 = x[1] * t4;
        let t7 = x[2] * t4;
        let t8 = x[3] * t4;
        let t9 = -t6;
        let t10 = -t7;
        let t11 = -t8;
        Translator::from_coeffs([t5, t9, t10, t11])
    }

    /// [`inverse`](Self::inverse), or `None` where `x` has no inverse to working precision:
    /// where `x ~x`, the Study number `N` the inverse divides by, is zero next to `x`
    /// (`|N| â¤ n Îµ âxâÂ²`, with `|N|Â²` and `âxâÂ²` the sums of the squared coefficients of `N`
    /// and `x`, and `n = 4` the number of `x`'s), or its norm `d = N conj(N)` is lost to
    /// cancellation (`|d| â¤ n Îµ |N|Â²`), in any lane; or where the inverse is not finite.
    #[inline]
    pub fn try_inverse(self) -> Option<Translator<(), T, O>> {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t3 = x[3] * x[3];
        let t4 = t0 * t0;
        let t5 = x[1].mul_add(x[1], t0);
        let t6 = x[2].mul_add(x[2], t3);
        let t7 = t5 + t6;
        let (size, d) = (t7, t4);
        let parts = t0 * t0;
        let tol = T::from_i64(4) * T::epsilon();
        if T::all_lt(tol * size, parts.sqrt()) && T::all_lt(tol * parts, d.abs()) {
            Some(self.inverse()).filter(gx::Extensor::is_finite)
        } else {
            None
        }
    }

    /// Scaled to a unit versor, `(x ~x)^(-1/2) x`, so that `x ~x = 1` (`Â±1` when the norm is negative).
    #[inline(always)]
    pub fn unit(self) -> gx::Unit<Self> {
        let x = self.c;
        let p0 = x[0] * x[0];
        let s0 = (p0).abs().sqrt().recip();
        let t0 = x[0] * s0;
        let t1 = x[1] * s0;
        let t2 = x[2] * s0;
        let t3 = x[3] * s0;
        gx::Unit::new_unchecked(Translator::from_coeffs([t0, t1, t2, t3]))
    }

    /// The same, uncertified: `self` scaled so that `x ~x = 1`, as a plain value. [`unit`](Self::unit)
    /// returns it as a [`gx::Unit`], which the cheaper unit kernels take.
    #[inline(always)]
    pub fn normalized(self) -> Self {
        self.unit().into_inner()
    }

}

impl<T: gx::Real> Translator<(), T, gx::Extrinsic> {
    /// Not callable: the logarithm is [`gx::Unit::log`], on a certified unit versor
    /// (`self.unit().log()`). This method only makes the compile error say so.
    #[doc(hidden)]
    #[inline(always)]
    pub fn log(self) -> Line<(), T, gx::Extrinsic>
    where
        Self: gx::__private::LogNeedsUnit<Line<(), T, gx::Extrinsic>>,
    {
        gx::__private::LogNeedsUnit::log(self)
    }

    /// The principal square root of a unit versor, `normalize(1 + R)` (not defined for `R = -1`).
    #[inline(always)]
    pub fn sqrt(self) -> gx::Unit<Self> {
        let mut c = self.c;
        c[0] = c[0] + T::one();
        Translator::from_coeffs(c).unit()
    }

}

impl<T: gx::Coef, O: gx::Orientation> gx::__private::NewtonStep for Translator<(), T, O> {
    /// `(3 â x ~x) x / 2`: one Newton step towards `x ~x = 1`, without a square root.
    #[inline(always)]
    fn newton_step(self) -> Self {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = t0 - T::from_i64(3);
        let t2 = x[0] * t0;
        let t3 = x[1] * t1;
        let t4 = x[2] * t1;
        let t5 = x[3] * t1;
        let t7 = x[0] * T::from_ratio(3, 2);
        let t8 = (-t2).mul_add(T::from_ratio(1, 2), t7);
        let t9 = t3 * T::from_ratio(1, 2);
        let t10 = -t9;
        let t11 = t4 * T::from_ratio(1, 2);
        let t12 = -t11;
        let t13 = t5 * T::from_ratio(1, 2);
        let t14 = -t13;
        Translator::from_coeffs([t8, t10, t12, t14])
    }

    #[inline(always)]
    fn note_renormalize() {
        T::note_renormalize();
    }
}

impl<T: gx::Real> gx::Log for Translator<(), T, gx::Extrinsic> {
    type Output = Line<(), T, gx::Extrinsic>;
    /// The logarithm of a unit versor: the bivector `B` with `B.exp() == self`.
    #[inline]
    #[allow(unused_variables)]
    fn log(unit: gx::Unit<Self>) -> Line<(), T, gx::Extrinsic> {
        T::vectorize(#[inline(always)] move || {
        let x = unit.into_inner().c;
        let [h0, h1] = gx::__private::study::log_coeffs(-1, (x[0], T::from_i64(0)), (T::from_i64(0), T::from_i64(0)));
        let t0 = x[1] * h0;
        let t1 = x[2] * h0;
        let t2 = x[3] * h0;
        Line::from_coeffs([T::from_i64(0), T::from_i64(0), T::from_i64(0), t0, t1, t2])
        })
    }
}

