impl<T: gx::Real, O: gx::Orientation> Flector<(), T, O> {
    /// The squared norm: the scalar part of `x ~x`.
    #[inline(always)]
    pub fn norm_squared(self) -> T {
        let x = self.c;
        let t1 = x[1] * x[1];
        let t3 = x[7] * x[7];
        let t4 = x[0].mul_add(x[0], t1);
        let t5 = x[2].mul_add(x[2], t3);
        let t6 = t4 + t5;
        t6
    }

    /// The norm, `sqrt(|norm_squared|)`.
    #[inline(always)]
    pub fn norm(self) -> T {
        self.norm_squared().abs().sqrt()
    }

    /// The inverse under the geometric product, `~x (x ~x)â»Â¹` (55 mul, 28 add, 1 div).
    #[inline(always)]
    pub fn inverse(self) -> Flector<(), T, O> {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[1] * x[1];
        let t2 = x[2] * x[2];
        let t3 = x[7] * x[7];
        let t6 = t0 * t2;
        let t8 = t1 * t1;
        let t10 = t1 * t3;
        let t13 = t3 * t3;
        let t14 = t0.mul_add(t0, t8);
        let t15 = t2.mul_add(t2, t13);
        let t16 = t14 + t15;
        let t17 = t0.mul_add(t1, t6);
        let t18 = t0.mul_add(t3, t17);
        let t19 = t1.mul_add(t2, t10);
        let t20 = t2.mul_add(t3, t19);
        let t21 = t18 + t20;
        let t23 = t21.mul_add(T::from_i64(2), t16);
        let t24 = t23.recip();
        let t25 = t0 * t24;
        let t26 = t1 * t24;
        let t27 = t2 * t24;
        let t28 = t3 * t24;
        let t29 = t25 + t26;
        let t30 = t27 + t28;
        let t31 = t29 + t30;
        let t32 = t25 - t26;
        let t33 = x[0] * x[4];
        let t35 = x[1] * x[5];
        let t36 = t24 * t35;
        let t37 = t24.mul_add(t33, t36);
        let t38 = t27 - t28;
        let t39 = x[2] * x[6];
        let t41 = x[3] * x[7];
        let t42 = t24 * t41;
        let t43 = t24.mul_add(t39, t42);
        let t44 = x[0] * x[1];
        let t45 = x[2] * x[7];
        let t46 = t24 * t44;
        let t47 = t24 * t45;
        let t48 = x[0] * t31;
        let t49 = x[1] * t31;
        let t50 = x[2] * t31;
        let t53 = x[3] * t38;
        let t54 = x[7] * t37;
        let t56 = x[0] * t43;
        let t57 = x[4] * t32;
        let t60 = x[1] * t43;
        let t62 = x[5] * t30;
        let t64 = x[2] * t37;
        let t66 = x[6] * t38;
        let t67 = x[7] * t31;
        let t68 = x[3].mul_add(t29, t53);
        let t69 = x[6].mul_add(t47, t54);
        let t71 = (-t69).mul_add(T::from_i64(2), t68);
        let t72 = (-x[4]).mul_add(t30, t57);
        let t73 = x[5].mul_add(t46, t56);
        let t75 = t73.mul_add(T::from_i64(2), t72);
        let t76 = x[5].mul_add(t32, t62);
        let t77 = x[4].mul_add(t46, t60);
        let t79 = t77.mul_add(T::from_i64(2), -t76);
        let t80 = (-x[6]).mul_add(t29, t66);
        let t81 = x[3].mul_add(t47, t64);
        let t83 = t81.mul_add(T::from_i64(2), t80);
        let t84 = -t67;
        Flector::from_coeffs([t48, t49, t50, t71, t75, t79, t83, t84])
    }

    /// [`inverse`](Self::inverse), or `None` where `x` has no inverse to working precision:
    /// where `x ~x`, the Study number `N` the inverse divides by, is zero next to `x`
    /// (`|N| â¤ n Îµ âxâÂ²`, with `|N|Â²` and `âxâÂ²` the sums of the squared coefficients of `N`
    /// and `x`, and `n = 8` the number of `x`'s), or its norm `d = N conj(N)` is lost to
    /// cancellation (`|d| â¤ n Îµ |N|Â²`), in any lane; or where the inverse is not finite.
    #[inline]
    pub fn try_inverse(self) -> Option<Flector<(), T, O>> {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[1] * x[1];
        let t2 = x[2] * x[2];
        let t3 = x[7] * x[7];
        let t5 = x[4] * x[4];
        let t9 = x[1] * x[5];
        let t11 = x[3] * x[7];
        let t14 = t0 * t2;
        let t16 = t1 * t1;
        let t18 = t1 * t3;
        let t21 = t3 * t3;
        let t22 = t0 + t1;
        let t23 = t2 + t3;
        let t24 = t22 + t23;
        let t25 = x[3].mul_add(x[3], t5);
        let t26 = x[5].mul_add(x[5], t25);
        let t27 = x[6].mul_add(x[6], t24);
        let t28 = t26 + t27;
        let t29 = x[0].mul_add(x[4], t9);
        let t30 = x[2].mul_add(x[6], t11);
        let t31 = t29 + t30;
        let t32 = t31 * T::from_i64(2);
        let t33 = -t32;
        let t34 = t0.mul_add(t0, t16);
        let t35 = t2.mul_add(t2, t21);
        let t36 = t34 + t35;
        let t37 = t0.mul_add(t1, t14);
        let t38 = t0.mul_add(t3, t37);
        let t39 = t1.mul_add(t2, t18);
        let t40 = t2.mul_add(t3, t39);
        let t41 = t38 + t40;
        let t43 = t41.mul_add(T::from_i64(2), t36);
        let (size, d) = (t28, t43);
        let parts = t24 * t24 + t33 * t33;
        let tol = T::from_i64(8) * T::epsilon();
        if T::all_lt(tol * size, parts.sqrt()) && T::all_lt(tol * parts, d.abs()) {
            Some(self.inverse()).filter(gx::Extensor::is_finite)
        } else {
            None
        }
    }

    /// Scaled to a unit versor, `(x ~x)^(-1/2) x`, so that `x ~x = 1` (`Â±1` when the norm is negative).
    #[inline(always)]
    pub fn unit(self) -> gx::Unit<Self> {
        let x = self.c;
        let p1 = x[1] * x[1];
        let p3 = x[7] * x[7];
        let p5 = x[1] * x[5];
        let p7 = x[3] * x[7];
        let p8 = x[0].mul_add(x[0], p1);
        let p9 = x[2].mul_add(x[2], p3);
        let p10 = p8 + p9;
        let p11 = x[0].mul_add(x[4], p5);
        let p12 = x[2].mul_add(x[6], p7);
        let p13 = p11 + p12;
        let p14 = p13 * T::from_i64(2);
        let p15 = -p14;
        let [s0, s1] = gx::__private::study::rsqrt_nil(p10, p15);
        let t0 = x[0] * s0;
        let t1 = x[1] * s0;
        let t2 = x[2] * s0;
        let t3 = x[3] * s0;
        let t6 = x[4] * s0;
        let t8 = x[5] * s0;
        let t10 = x[6] * s0;
        let t11 = x[7] * s0;
        let t12 = (-x[7]).mul_add(s1, t3);
        let t13 = (-x[0]).mul_add(s1, t6);
        let t14 = (-x[1]).mul_add(s1, t8);
        let t15 = (-x[2]).mul_add(s1, t10);
        gx::Unit::new_unchecked(Flector::from_coeffs([t0, t1, t2, t12, t13, t14, t15, t11]))
    }

    /// The same, uncertified: `self` scaled so that `x ~x = 1`, as a plain value. [`unit`](Self::unit)
    /// returns it as a [`gx::Unit`], which the cheaper unit kernels take.
    #[inline(always)]
    pub fn normalized(self) -> Self {
        self.unit().into_inner()
    }

}

impl<T: gx::Coef, O: gx::Orientation> gx::__private::NewtonStep for Flector<(), T, O> {
    /// `(3 â x ~x) x / 2`: one Newton step towards `x ~x = 1`, without a square root.
    #[inline(always)]
    fn newton_step(self) -> Self {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[1] * x[1];
        let t2 = x[2] * x[2];
        let t3 = x[7] * x[7];
        let t4 = t0 + t1;
        let t5 = t2 + t3;
        let t6 = t4 + t5;
        let t7 = t4 - T::from_i64(3);
        let t8 = t5 - T::from_i64(3);
        let t10 = x[1] * x[5];
        let t11 = x[0].mul_add(x[4], t10);
        let t13 = x[3] * x[7];
        let t14 = x[2].mul_add(x[6], t13);
        let t16 = (-t6).mul_add(T::from_ratio(1, 3), T::from_i64(1));
        let t17 = x[0] * x[1];
        let t18 = x[2] * x[7];
        let t19 = x[0] * t16;
        let t20 = x[1] * t16;
        let t21 = x[2] * t16;
        let t24 = x[3] * t3;
        let t25 = x[3] * t7;
        let t26 = x[7] * t11;
        let t27 = x[4] * t0;
        let t29 = x[0] * t14;
        let t31 = x[4] * t8;
        let t34 = x[5] * t1;
        let t35 = x[1] * t14;
        let t36 = x[5] * t8;
        let t37 = x[6] * t2;
        let t39 = x[2] * t11;
        let t41 = x[6] * t7;
        let t42 = x[7] * t16;
        let t43 = t19 * T::from_ratio(3, 2);
        let t44 = t20 * T::from_ratio(3, 2);
        let t45 = t21 * T::from_ratio(3, 2);
        let t46 = x[6].mul_add(t18, t26);
        let t47 = x[3].mul_add(t2, t25);
        let t50 = t47.mul_add(T::from_ratio(1, 2), t46);
        let t51 = t24.mul_add(T::from_ratio(3, 2), t50);
        let t52 = -t51;
        let t53 = x[5].mul_add(t17, t29);
        let t54 = x[4].mul_add(t1, t31);
        let t57 = t54.mul_add(T::from_ratio(1, 2), t53);
        let t58 = t27.mul_add(T::from_ratio(3, 2), t57);
        let t59 = -t58;
        let t60 = x[4].mul_add(t17, t35);
        let t61 = x[5].mul_add(t0, t36);
        let t64 = t61.mul_add(T::from_ratio(1, 2), t60);
        let t65 = t34.mul_add(T::from_ratio(3, 2), t64);
        let t66 = -t65;
        let t67 = x[3].mul_add(t18, t39);
        let t68 = x[6].mul_add(t3, t41);
        let t71 = t68.mul_add(T::from_ratio(1, 2), t67);
        let t72 = t37.mul_add(T::from_ratio(3, 2), t71);
        let t73 = -t72;
        let t74 = t42 * T::from_ratio(3, 2);
        Flector::from_coeffs([t43, t44, t45, t52, t59, t66, t73, t74])
    }

    #[inline(always)]
    fn note_renormalize() {
        T::note_renormalize();
    }
}

